@using Microsoft.AspNetCore.Components.Authorization

<Microsoft.AspNetCore.Components.Routing.NavigationLock OnBeforeInternalNavigation="OnBeforeNav" />

@code {
    [CascadingParameter]
    private Task<AuthenticationState>? AuthState { get; set; }

    [Inject]
    private NavigationManager Navigation { get; set; } = default!;

    protected override async Task OnInitializedAsync()
    {
        if (AuthState is not null)
        {
            var state = await AuthState;
            if (state.User.Identity?.IsAuthenticated != true)
            {
                Navigation.NavigateTo($"account/login?returnUrl={Uri.EscapeDataString(Navigation.Uri)}", forceLoad: true);
            }
        }
    }

    private void OnBeforeNav(LocationChangingContext context)
    {
        // Allow navigation
    }
